    "InitiatorUserId" uuid NOT NULL,
    "ContextJson" text,
    "StartedAt" timestamp with time zone NOT NULL,
    "CompletedAt" timestamp with time zone
);


ALTER TABLE public.workflow_runs OWNER TO medistock;

